for name, content in personal_files.items():
    name = name.replace('assets-video-diag', personal_assets)
    content = content.replace('assets-video-diag/', personal_assets + '/')
    target = personal / name
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content)
for path in personal.rglob('*.js'):
    subprocess.run(['node', '--input-type=module', '--check'], input=path.read_text(), text=True, check=True)
